from collections import deque
cells=[(i,j) for i in range(len(I)) for j in range(16) if I[i][j]==3]
S=set(cells)
def comp(start):
    seen={start}; q=deque([start])
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            n=(i+di,j+dj)
            if n in S and n not in seen: seen.add(n); q.append(n)
    return seen
comps=[]; seen=set()
for c in cells:
    if c not in seen:
        k=comp(c); comps.append(k); seen|=k
print(len(comps), [len(c) for c in comps])
# endpoints (exactly one orthogonal neighbor)
for i,j in sorted(cells):
    nb=sum(((i+di,j+dj) in S) for di,dj in((1,0),(-1,0),(0,1),(0,-1)))
    if nb==1: print('endpoint',(i,j))
# what's special about (7,4): topmost row of shape
top=min(i for i,j in cells); print('top row',top)
for i,j in sorted(cells):
    if i==top: print((i,j),'below:',(i+1,j) in S)
